import Link from "next/link";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";

export default async function Sidebar({ activeRoute }: { activeRoute: string }) {
  const session = await getServerSession(authOptions);
  const user = session?.user as any;

  const navItems = [
    { name: "Overview", href: "/dashboard" },
    { name: "Accounts", href: "/dashboard/accounts" },
    { name: "Transfers", href: "/dashboard/transfers" },
    { name: "Deposits", href: "/dashboard/deposits" },
    { name: "Withdrawals", href: "/dashboard/withdrawals" },
    { name: "Savings", href: "/dashboard/savings" },
    { name: "Investments", href: "/dashboard/investments" },
    { name: "Loans", href: "/dashboard/loans" },
    { name: "Statements", href: "/dashboard/statements" },
    { name: "Support", href: "/dashboard/support" },
    { name: "Settings", href: "/dashboard/settings" },
  ];

  return (
    <aside className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col hidden md:flex shrink-0">
      {/* User Profile Header */}
      <div className="p-5 border-b border-slate-800 flex items-center space-x-3">
        <div className="w-10 h-10 rounded-full bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 font-bold overflow-hidden shrink-0">
          {user?.image ? (
            <img src={user.image} alt={user.name || "User"} className="w-full h-full object-cover" />
          ) : (
            <span>{user?.name ? user.name.charAt(0).toUpperCase() : "C"}</span>
          )}
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-semibold text-white truncate">{user?.name || "Valued Client"}</p>
          <p className="text-[10px] text-slate-400 truncate">{user?.email || "client@civicbank.com"}</p>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = activeRoute === item.href;
          return (
            <Link
              key={item.name}
              href={item.href}
              className={`flex items-center px-4 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                isActive
                  ? "bg-indigo-600/10 text-indigo-400 border border-indigo-500/20"
                  : "text-slate-400 hover:bg-slate-800 hover:text-slate-200"
              }`}
            >
              <span>{item.name}</span>
            </Link>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-800">
        <Link
          href="/api/auth/signout"
          className="w-full flex items-center justify-center space-x-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 py-2 rounded-lg text-sm font-medium transition-colors border border-red-500/20"
        >
          <span>Sign Out</span>
        </Link>
      </div>
    </aside>
  );
}